import path from 'node:path';
import {
  createServer,
  loadConfigFromFile,
  type InlineConfig,
  type Plugin,
  type PluginOption,
  type UserConfig,
  type ViteDevServer,
} from 'vite';

import {
  PLUGIN_NAME,
  VIRTUAL_PAGE_HELPER_ID,
  RESOLVED_VIRTUAL_PAGE_HELPER_ID,
  VIRTUAL_LOCAL_TYPES_PREFIX,
} from './constants.js';
import { brand } from './brand.js';
import { PAGE_HELPER_MODULE_SOURCE } from './page-helper-generator.js';
import {
  loadEscapedPage,
  pageModuleUrl,
  resolveEscapedPageId,
} from './page-module-id.js';
import { isStructuredPageModule } from './render-runtime.js';
import type { HtPageModule } from './types.js';

export type PageModuleLoader = (
  entryPath: string,
  relativePath: string,
) => Promise<HtPageModule>;

export interface PageModuleLoaderHandle {
  loadModule: PageModuleLoader;
  close: () => Promise<void>;
}

/**
 * Duck-type the SSR environment instead of `isRunnableDevEnvironment`
 * (instanceof). Sitelo and the plugin can resolve different Vite copies
 * when linked locally, which makes instanceof fail even when a runner exists.
 */
function getSsrModuleRunner(server: ViteDevServer) {
  const environment = server.environments.ssr as
    | { runner?: { import: (url: string) => Promise<unknown> } }
    | undefined;

  const runner = environment?.runner;

  if (!runner || typeof runner.import !== 'function') {
    throw new Error(
      brand(
        'The Vite SSR environment is not runnable. ' +
          'A RunnableDevEnvironment is required to evaluate page modules.',
      ),
    );
  }

  return runner;
}

async function importPageModule(
  server: ViteDevServer,
  url: string,
): Promise<HtPageModule> {
  const runner = getSsrModuleRunner(server);
  const mod = await runner.import(url);

  return normalizeLoadedPageModule(mod);
}

export function isLocalPageTypesImport(id: string): boolean {
  return /^\.\/\$types(?:\.[A-Za-z0-9_.-]+)?$/.test(id);
}

function normalizeLoadedPageModule(mod: unknown): HtPageModule {
  const pageModule = (mod ?? {}) as HtPageModule;

  if (isStructuredPageModule(pageModule.default)) {
    const structured = pageModule.default;

    return {
      default: structured.render,
      data: structured.data,
      generateStaticParams: structured.generateStaticParams,
      dynamic: structured.dynamic,
      prerender: structured.prerender,
    };
  }

  return pageModule;
}

async function flattenPluginOptions(option: PluginOption): Promise<Plugin[]> {
  const resolved = await option;

  if (!resolved) return [];

  if (Array.isArray(resolved)) {
    const nested = await Promise.all(
      resolved.map((entry) => flattenPluginOptions(entry)),
    );
    return nested.flat();
  }

  return [resolved as Plugin];
}

async function loadUserConfig(args: {
  root: string;
  configFile: string | undefined;
  mode: string;
}): Promise<{ userConfig: UserConfig; userPlugins: Plugin[] }> {
  if (!args.configFile) {
    return { userConfig: {}, userPlugins: [] };
  }

  const loaded = await loadConfigFromFile(
    { command: 'serve', mode: args.mode },
    args.configFile,
    args.root,
  );

  if (!loaded) {
    return { userConfig: {}, userPlugins: [] };
  }

  const plugins = await flattenPluginOptions(loaded.config.plugins);

  return {
    userConfig: loaded.config,
    // Filter ourselves out so evaluating page modules does not
    // recursively spawn more build loaders.
    userPlugins: plugins.filter((plugin) => plugin.name !== PLUGIN_NAME),
  };
}

function createPageHelperPlugin(): Plugin {
  return {
    name: `${PLUGIN_NAME}:page-helper`,

    resolveId(id, importer) {
      if (id === VIRTUAL_PAGE_HELPER_ID) {
        return RESOLVED_VIRTUAL_PAGE_HELPER_ID;
      }

      if (importer && isLocalPageTypesImport(id)) {
        return `${VIRTUAL_LOCAL_TYPES_PREFIX}${importer}::${id}`;
      }

      return resolveEscapedPageId(id);
    },

    load(id) {
      const escapedPage = loadEscapedPage(id);
      if (escapedPage) return escapedPage;

      if (id.startsWith(VIRTUAL_LOCAL_TYPES_PREFIX)) {
        return `
export {
  definePage,
  defineData,
  defineStaticParams,
  definePageModule
} from 'vite-plugin-html-pages/page';
`;
      }

      if (id === RESOLVED_VIRTUAL_PAGE_HELPER_ID) {
        return PAGE_HELPER_MODULE_SOURCE;
      }

      return null;
    },
  };
}

export async function createPageModuleLoader(args: {
  mode: 'dev' | 'build';
  root: string;
  server?: ViteDevServer | null;
  configFile?: string;
  configMode?: string;
  /** The build's resolved `base`, which a `--base` flag never puts in the config file. */
  base?: string;
}): Promise<PageModuleLoaderHandle> {
  const { mode, root, server } = args;

  if (mode === 'dev') {
    if (!server) {
      throw new Error(brand('dev server not available'));
    }

    return {
      loadModule: async (entryPath, relativePath) =>
        importPageModule(server, pageModuleUrl(entryPath, relativePath)),
      close: async () => {},
    };
  }

  const configMode = args.configMode ?? 'production';

  // Load the user's Vite config so page modules are evaluated with the
  // same aliases, defines, and plugins as in dev.
  const { userConfig, userPlugins } = await loadUserConfig({
    root,
    configFile: args.configFile,
    mode: configMode,
  });

  const config: InlineConfig = {
    ...userConfig,
    root,
    // So import.meta.env.BASE_URL in a page module is what the dev
    // server gives it.
    base: args.base ?? userConfig.base,
    mode: configMode,
    configFile: false,
    logLevel: 'error',
    appType: 'custom',
    esbuild:
      userConfig.esbuild === false
        ? false
        : {
            ...userConfig.esbuild,
            jsx: 'automatic',
            jsxImportSource: PLUGIN_NAME,
          },
    server: {
      ...userConfig.server,
      middlewareMode: true,
      watch: null,
    },
    plugins: [...userPlugins, createPageHelperPlugin()],
  };

  const buildServer = await createServer(config);

  return {
    loadModule: async (entryPath) => {
      const relativePath = path.relative(root, entryPath).replace(/\\/g, '/');

      return importPageModule(
        buildServer,
        pageModuleUrl(entryPath, relativePath),
      );
    },
    close: async () => {
      await buildServer.close();
    },
  };
}
